#include <iostream>
#include <algorithm>
#include <fstream>
#include <vector>
#include <deque>
#include <assert.h>
#include <bitset>
#include <queue>
#include <stack>
#include <set>
#include <map>
#include <tuple>
#include <stdio.h>
#include <string.h>
#include <utility>
#include <math.h>
using namespace std;

inline int readInt(){int32_t x ; scanf("%d",&x) ; return x ; }
inline string readString(){char ch[1001000] ; scanf("%s",ch) ; return ch;}
template<typename T, typename U> inline T minimize(T &a, U b) { if (b < a) a = b; return a; }
template<typename T, typename U> inline T maximize(T &a, U b) { if (a < b) a = b; return a; }
#define mp make_pair
#define EPS 1e-9
typedef pair<int , int > pii;
typedef long double ld;
typedef unsigned long long ull;
typedef long long ll;
const int MAX_SIZE = 1e5 + 10;
const int PRIME_BASE = 29;
const int LOG_LIMIT = 21;
const int MOD_VALUE = 1e9 + 7;
const ll BIG_INF = 1e18;
int gridSize , timeLimit;
string gridA[30] , gridB[30];
int distStart[30][30] , distEnd[30][30];
int directionX[] = {0,0,-1,1};
int directionY[] = {1,-1,0,0};
struct FlowEdge
{
    int from , to , capacity , flow;
};
int level[MAX_SIZE];
int currentPtr[MAX_SIZE];
int BFSQueue[MAX_SIZE];
vector<FlowEdge> edges;
vector<int> adjList[MAX_SIZE];
int zeroPosX , zeroPosY;
int sourceNode , sinkNode;
inline void insertEdge(int a , int b , int cap)
{
    FlowEdge e1 = {a,b,cap,0};
    FlowEdge e2 = {b,a,0,0};
    adjList[a].push_back((int)edges.size());
    edges.push_back(e1);
    adjList[b].push_back((int)edges.size());
    edges.push_back(e2);
}
inline bool isValid(int x , int y){return (x >= 0 && x < gridSize && y >= 0 && y < gridSize);}
inline void computeDistances1(int x = zeroPosX , int y = zeroPosY)
{
    queue<pii> q;
    q.push({x,y});
    for (int i = 0 ; i <= 20 ; i ++)
        for (int j = 0 ; j <= 20 ; j ++)
            distStart[i][j] = 1e9;
    distStart[x][y] = 0;
    while (!q.empty())
    {
        int x = q.front().first , y = q.front().second;
        q.pop();
        for (int i = 0 ; i < 4 ; i ++)
        {
            int nx = x + directionX[i] , ny = y + directionY[i];
            if (isValid(nx,ny) && distStart[nx][ny] >= 1e9 && gridB[nx][ny] != 'Y')
            {
                distStart[nx][ny] = distStart[x][y] + 1;
                q.push({nx,ny});
            }
        }
    }

}
inline bool bfsLevel()
{
    memset(level,-1,gridSize * sizeof level[0]);
    int qh = 0 , qt = 0;
    BFSQueue[qt ++] = sourceNode;
    level[sourceNode] = 0;
    while (qh < qt && level[sinkNode] == -1)
    {
        int cur = BFSQueue[qh ++];
        for (int idx = 0 ; idx < adjList[cur].size() ; idx ++)
        {
            int eid = adjList[cur][idx] , dest = edges[eid].to;
            if (level[dest] == -1 && edges[eid].flow < edges[eid].capacity)
            {
                BFSQueue[qt ++] = dest;
                level[dest] = level[cur] + 1;
            }
        }
    }
    return level[sinkNode] != -1;
}
inline int dfsPath(int v , int flow)
{
    if (!flow) return 0;
    if (v == sinkNode) return flow;
    for ( ; currentPtr[v] < adjList[v].size() ; currentPtr[v] ++)
    {
        int eid = adjList[v][currentPtr[v]] , dest = edges[eid].to;
        if (level[dest] != level[v] + 1) continue;
        int flowSent = dfsPath(dest , min(flow , edges[eid].capacity - edges[eid].flow));
        if (flowSent)
        {
            edges[eid].flow += flowSent;
            edges[eid^1].flow -= flowSent;
            return flowSent;
        }
    }
    return 0;
}
inline int computeMaxFlow()
{
    int totalFlow = 0;
    while (true)
    {
        if (!bfsLevel()) break;
        memset(currentPtr,0,gridSize * sizeof currentPtr[0]);
        while (int flowSent = dfsPath(sourceNode , 1e9))
        {
            totalFlow += flowSent;
        }
    }
    return totalFlow;
}
inline void computeDistances2(int startX , int startY)
{
    queue<pii> q;
    q.push({startX,startY});
    for (int i = 0 ; i <= 20 ; i ++)
        for (int j = 0 ; j <= 20 ; j ++)
            distEnd[i][j] = 1e9;
    distEnd[startX][startY] = 0;
    while (!q.empty())
    {
        int x = q.front().first , y = q.front().second;
        q.pop();
        if (distEnd[x][y] >= distStart[x][y]) continue;
        for (int i = 0 ; i < 4 ; i++)
        {
            int nx = x + directionX[i] , ny = y + directionY[i];
            if(isValid(nx,ny) &&  distEnd[nx][ny] >= 1e9 && gridA[nx][ny] != 'Y' && distEnd[x][y] + 1 <= distStart[nx][ny])
            {
                distEnd[nx][ny] = distEnd[x][y] + 1;
                q.push({nx,ny});
            }
        }
    }
}
int32_t main()
{
    gridSize = readInt() , timeLimit = readInt();
    for (int i = 0 ; i < gridSize ; i ++)
        gridA[i] = readString();
    for (int i = 0 ; i < gridSize ; i ++)
    {
        gridB[i] = readString();
        for (int j = 0 ; j < gridSize ; j ++)
        {
            if (gridB[i][j] == 'Z')
            {
                gridB[i][j] = gridA[i][j] = 'Y';
                zeroPosX = i , zeroPosY = j;
            }
        }
    }
    computeDistances1();
    sourceNode = 0 , sinkNode = 2 * gridSize * gridSize + 1;
    for (int i = 0 ; i < gridSize ; i ++)
    {
        for (int j = 0 ; j < gridSize ; j ++)
        {
            if (gridA[i][j] == 'Y') continue;
            int id1 = i * gridSize + j + 1;
            int id2 = gridSize * gridSize + i * gridSize + j + 1;
            insertEdge(sourceNode,id1,gridA[i][j]-'0');
            insertEdge(id2,sinkNode,gridB[i][j]-'0');
            computeDistances2(i , j);
            for (int x = 0 ; x < gridSize ; x ++)
            {
                for (int y = 0 ; y < gridSize ; y ++)
                {
                    if (gridB[x][y] == 'Y' || distEnd[x][y] > timeLimit) continue;
                    insertEdge(id1,gridSize * gridSize + x * gridSize + y + 1 , gridA[i][j] - '0');
                }
            }
        }
    }
    gridSize = 2 * gridSize * gridSize + 5;

//    printf("%d\n",computeMaxFlow());
    cout << computeMaxFlow() << endl;
}
